package cn.jingyu.deepseek;
import android.content.*;import android.graphics.*;import android.graphics.drawable.Drawable;import android.view.*;import android.widget.*;
import java.util.*;import org.commonmark.node.Node;import io.noties.markwon.*;import io.noties.markwon.core.MarkwonTheme;import io.noties.markwon.ext.latex.JLatexMathPlugin;import io.noties.markwon.ext.tables.TablePlugin;import io.noties.markwon.inlineparser.MarkwonInlineParserPlugin;
/** Bundled native Markdown and LaTeX; no remote scripts, fonts or images. */
public final class RichText {
 private final int bodySize;private final Context context;private final int ink,accent,surface,border;private final Markwon markdown;private final LinkedHashMap<String,Node> parsed=new LinkedHashMap<String,Node>(16,.75f,true);private int cachedChars;public int parseCount;
 private int dp(float n){return (int)(context.getResources().getDisplayMetrics().density*n+.5f);}private float sp(float n){return context.getResources().getDisplayMetrics().scaledDensity*n;}
 public RichText(Context context,int ink,int accent,int surface,int border){this(context,ink,accent,surface,border,16);}
 public RichText(Context context,int ink,int accent,int surface,int border,int bodySize){this.bodySize=bodySize;this.context=context;this.ink=ink;this.accent=accent;this.surface=surface;this.border=border;ru.noties.jlatexmath.JLatexMathAndroid.init(context.getApplicationContext());
 markdown=Markwon.builder(context).usePlugin(MarkwonInlineParserPlugin.create()).usePlugin(JLatexMathPlugin.create(sp(bodySize),b->{b.inlinesEnabled(true);b.theme().textColor(ink).blockFitCanvas(true);b.errorHandler((latex,error)->new FormulaFallback(latex,ink,sp(13)));}))
 .usePlugin(TablePlugin.create(b->b.tableBorderColor(border).tableBorderWidth(dp(1)).tableCellPadding(dp(12)).tableHeaderRowBackgroundColor(surface).tableOddRowBackgroundColor(Color.TRANSPARENT)))
 .usePlugin(new AbstractMarkwonPlugin(){@Override public void configureTheme(MarkwonTheme.Builder b){b.linkColor(accent).blockQuoteColor(accent).blockQuoteWidth(dp(3)).blockMargin(dp(18)).bulletWidth(dp(4)).codeBackgroundColor(surface).codeBlockBackgroundColor(surface).codeTextColor(ink).codeBlockTextColor(ink).codeTextSize((int)sp(Math.max(12,bodySize-2))).codeBlockTextSize((int)sp(Math.max(12,bodySize-2))).headingBreakHeight(0).headingTextSizeMultipliers(new float[]{1.4f,1.25f,1.12f,1.06f,1f,1f}).thematicBreakColor(border);}}).build();}
 public TextView text(String value,int size){TextView view=new TextView(context);view.setTextColor(ink);view.setTextSize(size);view.setLineSpacing(dp(5),1.05f);view.setTextIsSelectable(true);view.setBreakStrategy(android.graphics.text.LineBreaker.BREAK_STRATEGY_SIMPLE);view.setText(value);return view;}
 public void set(TextView view,String raw){try{String normalized=normalize(raw);Node node=parsed.get(normalized);if(node==null){node=markdown.parse(normalized);parseCount++;if(normalized.length()<200000){parsed.put(normalized,node);cachedChars+=normalized.length();while(parsed.size()>64||cachedChars>1000000){String key=parsed.keySet().iterator().next();cachedChars-=key.length();parsed.remove(key);}}}markdown.setParsedMarkdown(view,markdown.render(node));}catch(Throwable error){view.setText(raw);}}
 private static final class LiveBlocks {final StreamBoundary boundary=new StreamBoundary();TextView tail;int rawEnd;String raw="",tailText="";}
 public TextView liveTail(LinearLayout host){LiveBlocks d=host.getTag() instanceof LiveBlocks?(LiveBlocks)host.getTag():null;return d==null?null:d.tail;}
 /** Each completed block owns its view; only the unfinished tail is edited on later frames. */
 public boolean updateLive(LinearLayout host,String raw){LiveBlocks d=host.getTag() instanceof LiveBlocks?(LiveBlocks)host.getTag():null;if(d!=null&&raw.equals(d.raw))return false;
  if(d==null||!d.boundary.accepts(raw)){host.removeAllViews();d=new LiveBlocks();d.tail=text("",bodySize);d.tail.setText("",TextView.BufferType.EDITABLE);host.addView(d.tail,new LinearLayout.LayoutParams(-1,-2));host.setTag(d);}
  java.util.List<Integer> cuts=d.boundary.append(raw);if(!cuts.isEmpty()){host.removeView(d.tail);for(int cut:cuts){if(cut>d.rawEnd){append(host,raw.substring(d.rawEnd,cut));d.rawEnd=cut;}}host.addView(d.tail,new LinearLayout.LayoutParams(-1,-2));d.tailText="";d.tail.setText("",TextView.BufferType.EDITABLE);}
  String tail=raw.substring(d.rawEnd);if(!tail.equals(d.tailText)){android.text.Editable editable=d.tail.getEditableText();if(tail.startsWith(d.tailText))editable.append(tail,d.tailText.length(),tail.length());else editable.replace(0,editable.length(),tail);d.tailText=tail;}d.tail.setVisibility(tail.isEmpty()?View.GONE:View.VISIBLE);d.raw=raw;return true;
 }
 public void append(LinearLayout parent,String raw){String[] lines=raw.replace("\r\n","\n").split("\n",-1);StringBuilder prose=new StringBuilder();
 for(int i=0;i<lines.length;){String trim=lines[i].trim();if(trim.startsWith("~~~")||trim.startsWith("\u0060\u0060\u0060")){flush(parent,prose);String marker=trim.substring(0,3),language=trim.substring(3).trim();StringBuilder code=new StringBuilder();i++;while(i<lines.length&&!lines[i].trim().startsWith(marker)){if(code.length()>0)code.append('\n');code.append(lines[i++]);}if(i<lines.length)i++;code(parent,language,code.toString());}
 else if(i+1<lines.length&&lines[i].contains("|")&&lines[i+1].trim().matches("\\|?\\s*:?-{3,}:?\\s*(\\|\\s*:?-{3,}:?\\s*)+\\|?")){flush(parent,prose);StringBuilder table=new StringBuilder(lines[i++]);int columns=Math.max(2,trim.replaceAll("^\\||\\|$","").split("\\|",-1).length);while(i<lines.length&&lines[i].contains("|")&&!lines[i].trim().isEmpty())table.append('\n').append(lines[i++]);TextView t=text("",14);t.setPadding(dp(1),dp(5),dp(1),dp(8));set(t,table.toString());int available=context.getResources().getDisplayMetrics().widthPixels-dp(44);HorizontalScrollView sc=new HorizontalScrollView(context);sc.setFillViewport(true);sc.addView(t,new HorizontalScrollView.LayoutParams(Math.max(available,dp(Math.min(columns,12)*124)),-2));parent.addView(sc,params());}
 else{prose.append(lines[i++]).append('\n');}}flush(parent,prose);}
 private LinearLayout.LayoutParams params(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(12);return p;}
 private void flush(LinearLayout parent,StringBuilder prose){String value=prose.toString().trim();prose.setLength(0);if(value.isEmpty())return;TextView t=text("",bodySize);set(t,value);parent.addView(t,params());}
 private void code(LinearLayout parent,String language,String value){LinearLayout panel=new LinearLayout(context);panel.setOrientation(LinearLayout.VERTICAL);panel.setBackground(UiKit.surface(surface,border,dp(12),0));LinearLayout top=new LinearLayout(context);top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(dp(13),dp(5),dp(8),0);TextView label=text(language.isEmpty()?"代码":language,11);label.setTextColor(accent);top.addView(label,new LinearLayout.LayoutParams(0,-2,1));TextView copy=text("复制",12);copy.setTextColor(accent);copy.setGravity(Gravity.CENTER);copy.setPadding(dp(12),dp(10),dp(12),dp(10));copy.setContentDescription("复制代码");copy.setOnClickListener(v->{((ClipboardManager)context.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("代码",value));Toast.makeText(context,"代码已复制",Toast.LENGTH_SHORT).show();});top.addView(copy);panel.addView(top);HorizontalScrollView sc=new HorizontalScrollView(context);TextView code=text("",Math.max(12,bodySize-2));code.setText(CodeHighlighter.highlight(language,value,Color.luminance(ink)>.5f));code.setTypeface(Typeface.MONOSPACE);code.setHorizontallyScrolling(true);code.setPadding(dp(14),dp(6),dp(18),dp(17));sc.addView(code,new HorizontalScrollView.LayoutParams(-2,-2));panel.addView(sc);parent.addView(panel,params());}
 /** Translate common math delimiters without touching escaped money or inline code. */
 public static String normalize(String raw){StringBuilder out=new StringBuilder();for(int i=0;i<raw.length();){char c=raw.charAt(i);if(c==96){int end=raw.indexOf(96,i+1);if(end>=0){out.append(raw,i,end+1);i=end+1;continue;}}
 if(c=='\\'&&i+1<raw.length()&&(raw.charAt(i+1)=='('||raw.charAt(i+1)=='[')){boolean block=raw.charAt(i+1)=='[';String close=block?"\\]":"\\)";int end=raw.indexOf(close,i+2);if(end>=0){if(block)out.append("\n\n");out.append("$$");if(block)out.append('\n');out.append(raw,i+2,end);if(block)out.append('\n');out.append("$$");if(block)out.append("\n\n");i=end+2;continue;}}
 if(c=='$'&&(i==0||raw.charAt(i-1)!='\\')){if(i+1<raw.length()&&raw.charAt(i+1)=='$'){int end=raw.indexOf("$$",i+2);if(end>=0){out.append(raw,i,end+2);i=end+2;continue;}}else{int end=i+1;while(end<raw.length()&&raw.charAt(end)!='\n'&&(raw.charAt(end)!='$'||raw.charAt(end-1)=='\\'))end++;if(end<raw.length()&&raw.charAt(end)=='$'){String formula=raw.substring(i+1,end);if(!formula.isEmpty()&&!Character.isWhitespace(formula.charAt(0))&&!Character.isWhitespace(formula.charAt(formula.length()-1))&&!formula.matches("[\\d., ]+")){out.append("$$").append(formula).append("$$");i=end+1;continue;}}}}
 out.append(c);i++;}return out.toString();}
 private static final class FormulaFallback extends Drawable {private final Paint paint=new Paint(3);private final String value;FormulaFallback(String value,int color,float size){this.value=value;paint.setColor(color);paint.setTextSize(size);paint.setTypeface(Typeface.MONOSPACE);setBounds(0,0,(int)Math.ceil(paint.measureText(value)),(int)Math.ceil(size*1.5f));}public void draw(Canvas c){c.drawText(value,getBounds().left,getBounds().top-paint.ascent(),paint);}public int getIntrinsicWidth(){return getBounds().width();}public int getIntrinsicHeight(){return getBounds().height();}public void setAlpha(int a){paint.setAlpha(a);}public void setColorFilter(ColorFilter filter){paint.setColorFilter(filter);}public int getOpacity(){return PixelFormat.TRANSLUCENT;}}
}
